// FORM SEVİYESİNDE DEĞİŞKENLER (En Üstte)
string[] ogrenciAdlari = new string[50];
int[] vizeler = new int[50];
int[] finaller = new int[50];
double[] ortalamalar = new double[50];
string[] harfNotlari = new string[50];

int toplamKayitliOgrenci = 0; // Sıradaki boş indeks

private void btnEkle_Click(object sender, EventArgs e)
{
    try
    {
        if (toplamKayitliOgrenci >= 50) { MessageBox.Show("Kontenjan Dolu!"); return; }
        if (string.IsNullOrWhiteSpace(txtAdSoyad.Text)) { MessageBox.Show("Adı boş bırakmayın!"); return; }

        int vize = Convert.ToInt32(txtVize.Text);
        int final = Convert.ToInt32(txtFinal.Text);
        if (vize < 0 || vize > 100 || final < 0 || final > 100) { MessageBox.Show("Notlar 0-100 arası olmalı!"); return; }

        double ort = (vize * 0.40) + (final * 0.60);
        string harf = "";
        if (ort >= 90) harf = "AA";
        else if (ort >= 80) harf = "BA";
        else if (ort >= 70) harf = "BB";
        else if (ort >= 60) harf = "CB";
        else if (ort >= 50) harf = "CC";
        else harf = "FF";

        // Diziye Yaz
        ogrenciAdlari[toplamKayitliOgrenci] = txtAdSoyad.Text;
        vizeler[toplamKayitliOgrenci] = vize;
        finaller[toplamKayitliOgrenci] = final;
        ortalamalar[toplamKayitliOgrenci] = ort;
        harfNotlari[toplamKayitliOgrenci] = harf;
        toplamKayitliOgrenci++;

        MessageBox.Show("Öğrenci Kaydedildi! Harf: " + harf);
        txtAdSoyad.Clear(); txtVize.Clear(); txtFinal.Clear(); txtAdSoyad.Focus();
    }
    catch { MessageBox.Show("Lütfen sayısal not giriniz!"); }
}

private void btnListele_Click(object sender, EventArgs e)
{
    if (toplamKayitliOgrenci == 0) { MessageBox.Show("Kayıtlı öğrenci yok!"); return; }
    listBoxKayitlar.Items.Clear();
    double sinifToplam = 0;
    int kalanSayisi = 0;

    // DÖNGÜ: Kapasite (50) değil, toplamKayitliOgrenci kadar döner!
    for (int i = 0; i < toplamKayitliOgrenci; i++)
    {
        string satir = (i + 1) + ") " + ogrenciAdlari[i] + " | Vize: " + vizeler[i] + 
                       " | Final: " + finaller[i] + " | Ort: " + ortalamalar[i].ToString("0.00") + 
                       " | Harf: [" + harfNotlari[i] + "]";
        listBoxKayitlar.Items.Add(satir);
        sinifToplam += ortalamalar[i];
        if (harfNotlari[i] == "FF") kalanSayisi++;
    }
    double sinifOrt = sinifToplam / toplamKayitliOgrenci;
    lblToplamKayit.Text   = "Toplam Öğrenci: " + toplamKayitliOgrenci;
    lblGenelOrtalama.Text = "Sınıf Ortalaması: " + sinifOrt.ToString("0.00");
    lblKalanSayisi.Text   = "Kalan (FF) Sayısı: " + kalanSayisi;
}

Bir öğrencinin notunu güncellemek için:
1. İndeks numarası belirlenir (Örn: secilenIndex = listBoxKayitlar.SelectedIndex).
2. O indeksteki dizi hücrelerine yeni değerler yazılır:
   vizeler[secilenIndex] = yeniVize;
   finaller[secilenIndex] = yeniFinal;
3. Ortalama ve harf notu yeniden hesaplanır.

double enYuksekOrtalama = ortalamalar[0];
string enBasariliOgrenci = ogrenciAdlari[0];

for (int i = 1; i < toplamKayitliOgrenci; i++)
{
    if (ortalamalar[i] > enYuksekOrtalama)
    {
        enYuksekOrtalama = ortalamalar[i];
        enBasariliOgrenci = ogrenciAdlari[i];
    }
}
lblDerece.Text = "Sınıf Birincisi: " + enBasariliOgrenci + " (" + enYuksekOrtalama.ToString("0.00") + ")";

Kullanıcı ListBox'taki bir öğrenciye tıkladığında (SelectedIndexChanged):
- int secilen = listBoxKayitlar.SelectedIndex;
- txtAdSoyad.Text = ogrenciAdlari[secilen];
- txtVize.Text = vizeler[secilen].ToString();
- txtFinal.Text = finaller[secilen].ToString();
Bu sayede seçilen öğrencinin bilgileri anında form kutularına geri dolar.

private void btnGuncelle_Click(object sender, EventArgs e)
{
    int secilen = listBoxKayitlar.SelectedIndex;
    if (secilen == -1) { MessageBox.Show("Lütfen bir öğrenci seçiniz!"); return; }

    // Yeni notları diziye yaz ve ortalamayı yeniden hesapla
    vizeler[secilen] = Convert.ToInt32(txtVize.Text);
    finaller[secilen] = Convert.ToInt32(txtFinal.Text);
    ortalamalar[secilen] = (vizeler[secilen] * 0.40) + (finaller[secilen] * 0.60);
    btnListele.PerformClick(); // Listeyi otomatik yenile
}

Bir butona basıldığında diğer butonun görevini otomatik çalıştırmak için:
- btnListele.PerformClick();
Bu komut, öğrenci eklendiğinde veya güncellendiğinde ListBox'ı tek satırda otomatik yeniler; kullanıcıyı tekrar Listele butonuna basma zahmetinden kurtarır.

